import java.util.*;

public class Ex04TreeMapSort {
    public static void main(String[] args) {
        TreeMap<String, Integer> tm = new TreeMap<>();
        String[] words = {"banana", "apple", "cherry"};
        for (String w : words) tm.put(w, w.length());
        System.out.println("natural order keys: " + tm.keySet());
        TreeMap<String, Integer> rev = new TreeMap<>(Comparator.reverseOrder());
        for (String w : words) rev.put(w, w.length());
        System.out.println("reverse order keys: " + rev.keySet());
    }
}
